"""Whole-request validation only; no numerical or replay engine."""
import json
class InvalidRequest(ValueError): pass
def bad(): raise InvalidRequest('invalid_request')
def loads(raw):
    def pairs(items):
        d={}
        for k,v in items:
            if k in d:bad()
            d[k]=v
        return d
    def constant(_):bad()
    try:
        if isinstance(raw,bytes):raw=raw.decode('utf-8')
        return json.loads(raw,object_pairs_hook=pairs,parse_constant=constant)
    except (ValueError,UnicodeError,RecursionError):bad()
def keys(x,names):
    if type(x) is not dict or set(x)!=set(names.split()):bad()
def integer(x,lo,hi):
    if type(x) is not int or not lo<=x<=hi:bad()
def sequence(x,lo,hi):
    if type(x) is not list or not lo<=len(x)<=hi:bad()
def path_ok(path,source,sink,edges):
    if path is None:return
    sequence(path,1,12);current=source;seen={source}
    for e in path:
        integer(e,0,len(edges)-1);u,v,_=edges[e]
        if u!=current or v in seen:bad()
        seen.add(v);current=v
    if current!=sink:bad()
def distinct(paths):
    values=[tuple(p) for p in paths if p is not None]
    if len(values)!=len(set(values)):bad()
def mode(x):
    if type(x) is not str or x not in ('route','admit'):bad()
def validate(v):
    keys(v,'cases');sequence(v['cases'],0,6);events_total=issues_total=0
    for case in v['cases']:
        keys(case,'nodes edges commodities workers quorum max_lag relax rho mode events')
        n=case['nodes'];integer(n,2,32)
        edges=case['edges'];sequence(edges,1,64);pairs=set()
        for edge in edges:
            sequence(edge,3,3);u,w,c=edge
            integer(u,0,n-1);integer(w,0,n-1);integer(c,0,1000)
            if u==w or (u,w) in pairs:bad()
            pairs.add((u,w))
        coms=case['commodities'];sequence(coms,0,24);slots=[]
        for com in coms:
            keys(com,'source sink demand paths');s,t=com['source'],com['sink']
            integer(s,0,n-1);integer(t,0,n-1)
            if s==t:bad()
            integer(com['demand'],0,1000);sequence(com['paths'],0,8)
            for p in com['paths']:path_ok(p,s,t,edges)
            distinct(com['paths']);slots.append(list(com['paths']))
        if sum(map(len,slots))>96:bad()
        workers=case['workers'];sequence(workers,1,8);ownership=[]
        for ids in workers:
            sequence(ids,0,len(coms))
            for k in ids:integer(k,0,len(coms)-1)
            if ids!=sorted(set(ids)):bad()
            ownership.extend(ids)
        if sorted(ownership)!=list(range(len(coms))):bad()
        integer(case['quorum'],1,len(workers));integer(case['max_lag'],0,12)
        sequence(case['relax'],2,2);a,b=case['relax']
        integer(a,1,16);integer(b,1,16)
        if not b<=a<2*b:bad()
        integer(case['rho'],1,8);mode(case['mode'])
        sequence(case['events'],1,256);events_total+=len(case['events'])
        tickets=set();saves={}
        for ev in case['events']:
            if type(ev) is not dict or type(ev.get('op')) is not str:bad()
            op=ev['op']
            if op=='configure':
                keys(ev,'op mode capacity demand paths');mode(ev['mode'])
                for field,size in [('capacity',len(edges)),('demand',len(coms))]:
                    sequence(ev[field],0,size);used=set()
                    for pair in ev[field]:
                        sequence(pair,2,2);i,x=pair;integer(i,0,size-1);integer(x,0,1000)
                        if i in used:bad()
                        used.add(i)
                sequence(ev['paths'],0,96);used=set()
                for change in ev['paths']:
                    sequence(change,3,3);k,p,path=change
                    integer(k,0,len(coms)-1);integer(p,0,len(slots[k])-1)
                    if (k,p) in used:bad()
                    used.add((k,p));path_ok(path,coms[k]['source'],coms[k]['sink'],edges);slots[k][p]=path
                for group in slots:distinct(group)
            elif op=='issue':
                keys(ev,'op id worker');integer(ev['id'],0,10**9);integer(ev['worker'],0,len(workers)-1)
                if ev['id'] in tickets:bad()
                tickets.add(ev['id']);issues_total+=1
            elif op=='deliver':
                keys(ev,'op id');integer(ev['id'],0,10**9)
                if ev['id'] not in tickets:bad()
            elif op=='retune':
                keys(ev,'op rho');integer(ev['rho'],1,8)
            elif op=='save':
                keys(ev,'op name');integer(ev['name'],0,10**9)
                if ev['name'] in saves:bad()
                saves[ev['name']]=[list(group) for group in slots]
            elif op=='restore':
                keys(ev,'op name');integer(ev['name'],0,10**9)
                if ev['name'] not in saves:bad()
                slots=[list(group) for group in saves[ev['name']]]
            elif op in ('step','audit'):keys(ev,'op')
            else:bad()
    if events_total>384 or issues_total>48:bad()
    return v

