"""Only compare tiny public examples; this is not the acceptance checker."""
import math
def compare(actual,expected,field=None):
    if type(expected) is int:
        if type(actual) is not int or actual!=expected:raise ValueError('public discrete value differs')
    elif type(expected) is float:
        if type(actual) not in (float,int) or not math.isfinite(actual):
            raise ValueError('expected finite number')
        if not -1e9<=actual<=1e9 or (expected>=0 and actual<0):
            raise ValueError('public example number outside range/sign')
        if expected==0 and field in ('flow','edge_load') and actual!=0:
            raise ValueError('public withdrawn amount/load must be exactly zero')
        if field!='edge_load' and abs(actual-expected)>1e-7+1e-7*max(abs(actual),abs(expected)):
            raise ValueError('public example number differs')
    elif type(expected) is dict:
        if type(actual) is not dict or set(actual)!=set(expected):raise ValueError('public example keys differ')
        for k in expected:compare(actual[k],expected[k],k)
    elif type(expected) is list:
        if type(actual) is not list or len(actual)!=len(expected):raise ValueError('public example dimensions differ')
        for a,b in zip(actual,expected):compare(a,b,field)
    elif type(actual) is not type(expected) or actual!=expected:raise ValueError('public example value differs')

def public_load_relation(response):
    # Only the canned one-edge, one-commodity proposal, not a full objective.
    for case in response.get('cases',[]):
        for event in case['events']:
            if event['op']=='issue' and event['result']['status']=='optimal':
                result=event['result'];amount=result['flow'][0][0];load=result['edge_load'][0]
                if abs(amount-load)>1e-7+1e-7*max(abs(amount),abs(load)):
                    raise ValueError('public edge load differs from amount')
