class WorkerSolver:
    """Solves the captured problem of a single path worker."""

    def __init__(self, num_edges: int):
        self._num_edges = int(num_edges)
        self._capacities: List[float] = [0.0] * self._num_edges
        self._demands: List[float] = []
        self._paths: List[List[Optional[List[int]]]] = []
        self._owned: List[int] = []
        self._bias: List[float] = [0.0] * self._num_edges
        self._rho: float = 1.0
        self._mode: str = 'route'

    # ------------------------------------------------------------------
    def configure(
        self,
        capacities: Sequence[float],
        demands: Sequence[float],
        paths: Sequence[List[Optional[List[int]]]],
        owned: Sequence[int],
        bias: Sequence[float],
        rho: float,
        mode: str,
    ) -> None:
        """Capture the immutable problem of one issue."""
        self._capacities = [float(value) for value in capacities]
        self._demands = [float(value) for value in demands]
        self._paths = [
            [None if path is None else list(path) for path in group] for group in paths
        ]
        self._owned = [int(value) for value in owned]
        self._bias = [float(value) for value in bias]
        self._rho = float(rho)
        self._mode = str(mode)

    # ------------------------------------------------------------------
    def available_slots(self, commodity: int) -> List[int]:
        """Slots of ``commodity`` whose path exists and only uses live edges."""
        slots: List[int] = []
        for slot, path in enumerate(self._paths[commodity]):
            if not path:
                continue
            if all(self._capacities[edge] > 0.0 for edge in path):
                slots.append(slot)
        return slots

    def _unroutable(self) -> List[int]:
        return sorted(
            commodity
            for commodity in self._owned
            if self._demands[commodity] > 0.0 and not self.available_slots(commodity)
        )

    # ------------------------------------------------------------------
    def solve(self) -> dict:
        """Return the immutable proposal of this worker."""
        owned = list(self._owned)
        if self._mode == 'route':
            unroutable = self._unroutable()
            if unroutable:
                return {'status': 'infeasible', 'unroutable': unroutable}

        groups: List[dict] = []
        var_paths: List[Tuple[int, ...]] = []
        for commodity in owned:
            demand = self._demands[commodity]
            if demand <= 0.0:
                continue
            slots = self.available_slots(commodity)
            if not slots:
                continue
            variables: List[int] = []
            for slot in slots:
                variables.append(len(var_paths))
                var_paths.append(tuple(self._paths[commodity][slot]))
            groups.append(
                {'commodity': commodity, 'vars': variables, 'demand': float(demand)}
            )

        num_vars = len(var_paths)
        hessian = np.eye(num_vars, dtype=np.float64)
        linear = np.zeros(num_vars, dtype=np.float64)
        if num_vars:
            edge_vars: Dict[int, List[int]] = {}
            for index, path in enumerate(var_paths):
                for edge in path:
                    edge_vars.setdefault(edge, []).append(index)
            for edge, variables in edge_vars.items():
                weight = self._rho / (self._capacities[edge] * self._capacities[edge])
                for first in variables:
                    hessian[first, first] += weight
                    for second in variables:
                        if second != first:
                            hessian[first, second] += weight
            for index, path in enumerate(var_paths):
                total = 0.0
                for edge in path:
                    capacity = self._capacities[edge]
                    total += self._bias[edge] / (capacity * capacity)
                linear[index] = -self._rho * total
                if self._mode == 'admit':
                    linear[index] -= 1.0

        amounts, multipliers = _solve_budget_qp(hessian, linear, groups, self._mode)
        if num_vars:
            # Safety net: repair the primal residual of every budget.
            repaired = False
            for group in groups:
                used = float(np.sum(amounts[group['vars']]))
                if group['vars'] and abs(used - group['demand']) > 1e-9 * max(1.0, group['demand']):
                    repaired = True
            if repaired:
                polished = _gradient_fallback(hessian, linear, groups, self._mode, amounts)
                amounts, multipliers = _solve_budget_qp(hessian, linear, groups, self._mode)
                if float(np.max(np.abs(polished - amounts))) > 1e-6:
                    amounts = polished

        # Amounts per owned commodity and slot.
        flow: List[List[float]] = []
        potentials: List[float] = []
        for commodity in owned:
            slots: List[float] = []
            for slot in range(len(self._paths[commodity])):
                slots.append(0.0)
            flow.append(slots)
        for group in groups:
            commodity = group['commodity']
            position = owned.index(commodity)
            for var, slot in zip(group['vars'], self.available_slots(commodity)):
                value = float(amounts[var])
                if value < 0.0:
                    value = 0.0
                flow[position][slot] = value
        for group, multiplier in zip(groups, multipliers):
            potentials.append(0.0)
        for group, multiplier in zip(groups, multipliers):
            position = owned.index(group['commodity'])
            potentials[position] = float(multiplier)

        # Edge loads of the worker (raw amounts, not normalised).
        loads = [0.0] * self._num_edges
        for group in groups:
            position = owned.index(group['commodity'])
            for var, slot in zip(group['vars'], self.available_slots(group['commodity'])):
                amount = flow[position][slot]
                if amount == 0.0:
                    continue
                for edge in var_paths[var]:
                    loads[edge] += amount

        return {
            'status': 'optimal',
            'flow': flow,
            'edge_load': loads,
            'potential': potentials,
        }


def solve_worker(
    capacities: Sequence[float],
    demands: Sequence[float],
    paths: Sequence[List[Optional[List[int]]]],
    owned: Sequence[int],
    bias: Sequence[float],
    rho: float,
    mode: str,
) -> dict:
    """Convenience wrapper around :class:`WorkerSolver`."""
    solver = WorkerSolver(len(capacities))
    solver.configure(capacities, demands, paths, owned, bias, rho, mode)
    return solver.solve()
