                    hessian[first, first] += weight
                    for second in variables:
                        if second != first:
                            hessian[first, second] += weight
            for index, path in enumerate(var_paths):
                total = 0.0
                for edge in path:
                    capacity = self._capacities[edge]
                    total += self._bias[edge] / (capacity * capacity)
                linear[index] = -self._rho * total
                if self._mode == 'admit':
                    linear[index] -= 1.0

        amounts, multipliers = _solve_budget_qp(hessian, linear, groups, self._mode)
        if num_vars:
            violation = 0.0
            for group in groups:
                used = float(np.sum(amounts[group['vars']]))
                if self._mode == 'route':
                    violation = max(violation, abs(used - group['demand']))
                else:
                    violation = max(violation, used - group['demand'])
            if violation > 1e-9 * max(1.0, float(np.max([g['demand'] for g in groups]))):
                polished = _gradient_fallback(hessian, linear, groups, self._mode, amounts)
                if self._mode == 'route':
                    polished = _project_groups(polished, groups, self._mode)
                if float(np.max(np.abs(polished - amounts))) < violation:
                    amounts = polished

        position_of = {commodity: index for index, commodity in enumerate(owned)}
        flow: List[List[float]] = []
        for commodity in owned:
            flow.append([0.0] * len(self._paths[commodity]))
        potentials: List[float] = [0.0] * len(owned)
        for group, multiplier in zip(groups, multipliers):
            position = position_of[group['commodity']]
            potentials[position] = float(multiplier)
            for var, slot in zip(group['vars'], self.available_slots(group['commodity'])):
                value = float(amounts[var])
                if value < 0.0:
                    value = 0.0
                flow[position][slot] = value

        # Edge loads of the worker (raw amounts, not normalised).
        loads = [0.0] * self._num_edges
        for group in groups:
            position = position_of[group['commodity']]
            for var, slot in zip(group['vars'], self.available_slots(group['commodity'])):
                amount = flow[position][slot]
                if amount == 0.0:
                    continue
                for edge in var_paths[var]:
                    loads[edge] += amount

        return {
            'status': 'optimal',
            'flow': flow,
            'edge_load': loads,
            'potential': potentials,
        }


def solve_worker(
    capacities: Sequence[float],
    demands: Sequence[float],
    paths: Sequence[List[Optional[List[int]]]],
    owned: Sequence[int],
    bias: Sequence[float],
    rho: float,
    mode: str,
) -> dict:
    """Convenience wrapper around :class:`WorkerSolver`."""
    solver = WorkerSolver(len(capacities))
    solver.configure(capacities, demands, paths, owned, bias, rho, mode)
    return solver.solve()
