"""Direct stress test of the worker solver with KKT verification."""
import random
import sys
import os

sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'submission'))
import numpy as np
from te.algorithms.formulations.path_based.distributed.worker import WorkerSolver


def tol(a, b):
    return 1e-7 + 1e-7 * max(abs(a), abs(b))


def check_case(rng, mode, num_commodities, slots, capacities, bias_scale):
    num_edges = len(capacities)
    commodities = []
    for _ in range(num_commodities):
        paths = []
        for _ in range(slots):
            length = rng.randint(1, 4)
            path = []
            node = 0
            for _ in range(length):
                path.append(rng.randrange(num_edges))
            paths.append(path)
        # distinct paths
        seen = set()
        unique = []
        for path in paths:
            key = tuple(path)
            if key in seen:
                continue
            seen.add(key)
            unique.append(path)
        commodities.append({'source': 0, 'sink': 1, 'demand': rng.choice([0, 1, 5, 100, 1000]),
                            'paths': unique})
    demands = [c['demand'] for c in commodities]
    paths = [c['paths'] for c in commodities]
    bias = [rng.uniform(-bias_scale, bias_scale) for _ in range(num_edges)]
    rho = rng.choice([1, 2, 8])
    solver = WorkerSolver(num_edges)
    solver.configure(capacities, demands, paths, list(range(num_commodities)), bias, rho, mode)
    result = solver.solve()
    if result['status'] != 'optimal':
        return None
    flow = result['flow']
    potential = result['potential']
    loads = result['edge_load']
    problems = []
    # recompute loads
    recomputed = [0.0] * num_edges
    for k in range(num_commodities):
        for p, amount in enumerate(flow[k]):
            path = paths[k][p]
            if amount < 0:
                problems.append('negative amount')
            for e in path:
                recomputed[e] += amount
    for e in range(num_edges):
        if abs(loads[e] - recomputed[e]) > tol(loads[e], recomputed[e]):
            problems.append('load mismatch %r %r' % (loads[e], recomputed[e]))
    for k in range(num_commodities):
        used = sum(flow[k])
        if demands[k] == 0 and used != 0:
            problems.append('zero demand carries traffic')
        if mode == 'route' and abs(used - demands[k]) > tol(used, demands[k]):
            problems.append('route budget %r != %r' % (used, demands[k]))
        if mode == 'admit' and used > demands[k] + tol(used, demands[k]):
            problems.append('admit budget exceeded')
        if mode == 'admit' and potential[k] < -1e-9:
            problems.append('negative admit potential %r' % potential[k])
    total = 0.0
    R = 0.0
    for k in range(num_commodities):
        for p, amount in enumerate(flow[k]):
            R += amount
            g = amount
            for e in paths[k][p]:
                if capacities[e] > 0:
                    g += rho * (recomputed[e] / capacities[e] - bias[e]) / capacities[e]
            if mode == 'admit':
                g -= 1.0
            total += amount * g
            if g + potential[k] < -tol(g, potential[k]):
                problems.append('KKT violation %r' % (g + potential[k]))
    f = 0.5 * sum(a * a for k in range(num_commodities) for a in flow[k])
    for e in range(num_edges):
        if capacities[e] > 0:
            f += 0.5 * rho * (recomputed[e] / capacities[e] - bias[e]) ** 2
    if mode == 'admit':
        f -= R
    D = f - total - sum(demands[k] * potential[k] for k in range(num_commodities))
    if abs(f - D) > tol(f, D):
        problems.append('identity %r %r' % (f, D))
    return problems


def main():
