#!/usr/bin/env python3
"""Certified sharing replay.

One UTF-8 JSON request is read from stdin to EOF and one JSON response is
written to stdout.  The whole request is validated before the replay starts,
so an illegal request never produces partial results.
"""
import json
import math
import sys

from protocol import InvalidRequest, loads, validate
from te.session import run_case


def _finite(value):
    """Replace a non finite number by zero; the protocol forbids them."""
    if isinstance(value, float):
        return value if math.isfinite(value) else 0.0
    if isinstance(value, list):
        return [_finite(item) for item in value]
    if isinstance(value, dict):
        return {key: _finite(item) for key, item in value.items()}
    return value


def solve(request):
    """Replay every case of the request."""
    return {'cases': [run_case(case) for case in request['cases']]}


def main():
    try:
        result = solve(validate(loads(sys.stdin.buffer.read())))
    except InvalidRequest:
        result = {'error': 'invalid_request'}
    sys.stdout.write(json.dumps(_finite(result), allow_nan=False, separators=(',', ':')))
    sys.stdout.write('\n')
    sys.stdout.flush()


if __name__ == '__main__':
    main()
